input.new_string:
    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    #[test]
    fn handles_empty_quoted_values() {
        let content = "DOUBLE=\"\"\nSINGLE=''";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("DOUBLE"), Some(&"".to_string()));
        assert_eq!(vars.get("SINGLE"), Some(&"".to_string()));
    }

    #[test]
    fn handles_mismatched_quotes() {
        let content = "MIX1=\"value'\nMIX2='value\"";

        let vars = EnvFileParser::parse(content).unwrap();

        // Mismatched quotes are not stripped
        assert_eq!(vars.get("MIX1"), Some(&"\"value'".to_string()));
        assert_eq!(vars.get("MIX2"), Some(&"'value\"".to_string()));
    }

    #[test]
    fn handles_value_with_only_opening_quote() {
        let content = "KEY=\"unterminated";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY"), Some(&"\"unterminated".to_string()));
    }

    #[test]
    fn handles_single_quote_character_value() {
        let content = "D=\"\nS='";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("D"), Some(&"\"".to_string()));
        assert_eq!(vars.get("S"), Some(&"'".to_string()));
    }

    #[test]
    fn handles_escaped_quotes_inside_double_quotes() {
        let content = r#"KEY="value with \"escaped\" quotes""#;

        let vars = EnvFileParser::parse(content).unwrap();

        // The parser does not process escape sequences — it only strips
        // the outermost matching quotes. The backslash-escaped inner
        // quotes cause the outer quotes to no longer match (the value
        // starts with `"` but ends with `"`), so the raw value is
        // returned as-is after the outermost pair is stripped.
        let value = vars.get("KEY").unwrap();
        assert!(value.contains("\\\""));
    }

    #[test]
    fn handles_escaped_characters_in_values() {
        let content = "PATH=\"/home/user\\\\bin\"\nTAB=\"col1\\tcol2\"";

        let vars = EnvFileParser::parse(content).unwrap();

        // Parser does not interpret escape sequences — backslashes are literal
        assert_eq!(vars.get("PATH"), Some(&"/home/user\\\\bin".to_string()));
        assert_eq!(vars.get("TAB"), Some(&"col1\\tcol2".to_string()));
    }

    #[test]
    fn handles_hash_inside_quotes() {
        let content = "COLOR=\"#ff0000\"\nMSG='hello # world'";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("COLOR"), Some(&"#ff0000".to_string()));
        assert_eq!(vars.get("MSG"), Some(&"hello # world".to_string()));
    }

    #[test]
    fn inline_comment_not_stripped_from_unquoted_value() {
        let content = "KEY=value # this is kept";

        let vars = EnvFileParser::parse(content).unwrap();

        // The parser does not strip inline comments
        assert_eq!(vars.get("KEY"), Some(&"value # this is kept".to_string()));
    }

    #[test]
    fn duplicate_keys_last_wins() {
        let content = "KEY=first\nKEY=second\nKEY=third";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY"), Some(&"third".to_string()));
    }

    #[test]
    fn handles_line_with_only_equals() {
        let content = "=";

        let vars = EnvFileParser::parse(content).unwrap();

        // Empty key with empty value
        assert_eq!(vars.get(""), Some(&"".to_string()));
    }

    #[test]
    fn handles_line_starting_with_equals() {
        let content = "=some_value";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get(""), Some(&"some_value".to_string()));
    }

    #[test]
    fn handles_whitespace_only_lines() {
        let content = "KEY1=a\n   \n\t\nKEY2=b";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 2);
        assert_eq!(vars.get("KEY1"), Some(&"a".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"b".to_string()));
    }

    #[test]
    fn handles_whitespace_only_value() {
        let content = "KEY=   ";

        let vars = EnvFileParser::parse(content).unwrap();

        // Value is trimmed
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn preserves_inner_whitespace_in_quoted_values() {
        let content = "KEY=\"  leading and trailing  \"";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(
            vars.get("KEY"),
            Some(&"  leading and trailing  ".to_string())
        );
    }

    #[test]
    fn handles_export_prefix_as_key_part() {
        let content = "export KEY=value";

        let vars = EnvFileParser::parse(content).unwrap();

        // Parser does not strip `export` — it becomes part of the key
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert!(vars.get("KEY").is_none());
    }

    #[test]
    fn handles_unicode_values() {
        let content = "GREETING=\"\u{00e9}\u{00e0}\u{00fc}\"\nEMOJI=\u{1f680}\u{1f30d}";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("GREETING"), Some(&"\u{00e9}\u{00e0}\u{00fc}".to_string()));
        assert_eq!(vars.get("EMOJI"), Some(&"\u{1f680}\u{1f30d}".to_string()));
    }

    #[test]
    fn handles_value_with_multiple_equals() {
        let content = "EXPR=a=b=c=d";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("EXPR"), Some(&"a=b=c=d".to_string()));
    }

    #[test]
    fn handles_quoted_value_with_equals() {
        let content = "CONN=\"host=localhost port=5432\"";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(
            vars.get("CONN"),
            Some(&"host=localhost port=5432".to_string())
        );
    }

    #[test]
    fn handles_quotes_inside_value() {
        let content = "KEY=he said \"hello\"";

        let vars = EnvFileParser::parse(content).unwrap();

        // Quotes are not outer-matching, so value is kept as-is
        assert_eq!(
            vars.get("KEY"),
            Some(&"he said \"hello\"".to_string())
        );
    }

    #[test]
    fn handles_single_character_quoted_value() {
        let content = "D=\"x\"\nS='y'";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("D"), Some(&"x".to_string()));
        assert_eq!(vars.get("S"), Some(&"y".to_string()));
    }

    #[test]
    fn parses_empty_content() {
        let vars = EnvFileParser::parse("").unwrap();

        assert!(vars.is_empty());
    }

    #[test]
    fn parses_content_with_only_comments() {
        let content = "# comment 1\n# comment 2\n# comment 3";

        let vars = EnvFileParser::parse(content).unwrap();

        assert!(vars.is_empty());
    }

    #[test]
    fn load_reads_file_from_disk() {
        let dir = tempfile::tempdir().unwrap();
        let file_path = dir.path().join(".env");
        std::fs::write(&file_path, "FROM_FILE=yes\nNUM=42").unwrap();

        let vars = EnvFileParser::load(&file_path).unwrap();

        assert_eq!(vars.get("FROM_FILE"), Some(&"yes".to_string()));
        assert_eq!(vars.get("NUM"), Some(&"42".to_string()));
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/nonexistent/path/.env"));

        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let dir = tempfile::tempdir().unwrap();
        let file_path = dir.path().join(".env");
        std::fs::write(&file_path, "OPT=present").unwrap();

        let vars = EnvFileParser::load_optional(&file_path).unwrap();

        assert_eq!(vars.get("OPT"), Some(&"present".to_string()));
    }

    #[test]
    fn handles_carriage_return_line_endings() {
        let content = "KEY1=val1\r\nKEY2=val2\r\n";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY1"), Some(&"val1".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"val2".to_string()));
    }

    #[test]
    fn handles_key_with_no_value_after_equals() {
        let content = "A=\nB=\"\"\nC=''";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("A"), Some(&"".to_string()));
        assert_eq!(vars.get("B"), Some(&"".to_string()));
        assert_eq!(vars.get("C"), Some(&"".to_string()));
    }

    #[test]
    fn handles_nested_quotes() {
        let content = "KEY=\"it's a test\"\nKEY2='say \"hi\"'";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY"), Some(&"it's a test".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"say \"hi\"".to_string()));
    }
}

